"""Verify source preservation, migration completeness and PDF solution exclusion."""
import sys
sys.dont_write_bytecode = True
from collections import Counter
from pathlib import Path
import hashlib
import json
import re
import logging
from pypdf import PdfReader
from pypdf.generic import ContentStream
from inventory import ROOT, read_tex, uncomment
from cache_paths import CACHE_ROOT
logging.getLogger('pypdf').setLevel(logging.ERROR)


def imported_forms(container):
    """Find original PDF forms inside the clipping forms generated by graphicx."""
    result = []
    for reference in container.get('/Resources', {}).get('/XObject', {}).values():
        form = reference.get_object()
        if form.get('/PTEX.PageNumber'):
            result.append(form)
        elif form.get('/Subtype') == '/Form':
            result.extend(imported_forms(form))
    return result


def import_bounds(page, reader, text_height):
    """Check uniform crop and maximal proportional fit inside the text area."""
    matrix=(1,0,0,1,0,0)
    stack=[]
    objects=page.get('/Resources',{}).get('/XObject',{})
    for operands,op in ContentStream(page.get_contents(),reader).operations:
        if op==b'q': stack.append(matrix)
        elif op==b'Q': matrix=stack.pop()
        elif op==b'cm':
            a,b,c,d,e,f=matrix
            g,h,i,j,k,l=map(float,operands)
            matrix=(a*g+c*h,b*g+d*h,a*i+c*j,b*i+d*j,a*k+c*l+e,b*k+d*l+f)
        elif op==b'Do' and operands[0] in objects:
            form=objects[operands[0]].get_object()
            originals = imported_forms(form)
            if not originals: continue
            assert len(originals) == 1, 'Expected one original page per clipping form'
            original = originals[0]
            ox0,oy0,ox1,oy1 = map(float,original['/BBox'])
            fx0,fy0,fx1,fy1 = map(float,form['/BBox'])
            assert abs((fx1-fx0)-(ox1-ox0)) < .02, 'Unexpected side crop'
            assert abs((fy1-fy0)-((oy1-oy0)-25*72/25.4)) < .02, 'Unexpected vertical crop'
            shifts = [list(map(float,ops)) for ops,operation in ContentStream(form,reader).operations if operation==b'cm']
            assert len(shifts)==1 and abs(shifts[0][5]+7*72/25.4)<.02, 'Unexpected bottom crop'
            a,b,c,d,e,f=matrix
            assert abs((a*a+b*b)-(c*c+d*d))<0.0001, 'Distorted imported PDF'
            assert abs(a*c+b*d)<0.0001, 'Sheared imported PDF'
            x0,y0,x1,y1=map(float,form['/BBox'])
            points=[(a*x+c*y+e,b*x+d*y+f) for x in (x0,x1) for y in (y0,y1)]
            width = max(x for x,y in points)-min(x for x,y in points)
            height = max(y for x,y in points)-min(y for x,y in points)
            target_width, target_height = 180*72/25.4, text_height*72/72.27
            assert width<=target_width+.1 and height<=target_height+.1, 'Solution exceeds text area'
            assert min(abs(width-target_width),abs(height-target_height))<.1, 'Solution is not maximally enlarged'
            assert min(x for x,y in points)>=-1 and max(x for x,y in points)<=float(page.mediabox.width)+1
            assert min(y for x,y in points)>=-1 and max(y for x,y in points)<=float(page.mediabox.height)+1


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def numbers(text):
    text = uncomment(text)
    text = re.sub(r'\\begin\{Solution\}.*?\\end\{Solution\}', '', text, flags=re.S)
    text = re.sub(r'\\ExerciseHeading\{[^{}]*\}\{[^{}]*\}\{[^{}]*\}', '', text)
    text = re.sub(r'\\(?:includepdf|includegraphics)(?:\[[^\]]*\])?\{[^{}]*\}', '', text)
    text = re.sub(r'\\begin\{enumerate\}(?:\[[^\]]*\])?', '', text)
    text = re.sub(r'\\setlength\{\\[A-Za-z]+\}\{[^{}]*\}', '', text)
    return re.findall(r'\d+(?:[.,]\d+)?', text)


def verify():
    helper_suffixes = ('.aux', '.log', '.fls', '.fdb_latexmk', '.out', '.toc', '.synctex.gz', '.pyc')
    assert not [p for p in ROOT.iterdir() if p.is_file() and (p.name.endswith(helper_suffixes) or p.suffix == '.pdf')], 'Build artifact in project root'
    assert not [p for p in (ROOT/'build').rglob('*') if p.is_file() and p.suffix != '.pdf'], 'Non-PDF build artifact in project'
    assert not list((ROOT/'tools').rglob('__pycache__')), 'Python cache in project'
    assert not (ROOT/'script_reference').exists(), 'Removed script source archive has returned'
    assert not (ROOT/'build/direct').exists(), 'Removed direct build has returned'
    reference = PdfReader(ROOT/'references/build-de.pdf')
    assert len(reference.pages) > 0, 'Empty script reference PDF'
    migration = json.loads((ROOT/'tools/migration_manifest.json').read_text(encoding='utf-8'))
    inventory = {'files':migration['relocated_assets']}
    for entry in migration['relocated_assets']:
        assert sha(ROOT/entry['path']).lower() == entry['sha256'].lower(), entry['path']
    records = migration['exercises']
    chapters = dict.fromkeys(r['chapter'] for r in records)
    summaries = []
    for chapter in chapters:
        tasks = [r for r in records if r['chapter']==chapter]
        assert len(tasks)==len(set(r['id'] for r in tasks))
        includes = re.findall(r'\\input\{([^{}]+)\}', (ROOT/f'content/chapters_de/{chapter}/_chapter.tex').read_text(encoding='utf-8'))
        assert includes==[r['target'] for r in tasks]
        expected_solution_pages = 0
        expected_streams = []
        for i,r in enumerate(tasks):
            target = (ROOT/r['target']).read_text(encoding='utf-8')
            assert target.count('\\UseExerciseSolution{'+r['id']+'}')==1, r['id']
            assert len(re.findall(r'\\item\b',target))==r['source_item_count'], r['id']
            assert not re.search(r'label=\(',target), ('Opening parenthesis in enumeration',r['id'])
            if not any(c['kind']=='mathematics' for c in r['changes']):
                assert r['source_numbers']==numbers(target), (r['id'], r['source_numbers'], numbers(target))
            for dep in r['dependencies']:
                if dep['kind']=='includepdf':
                    assert dep['options']=='pages=-', dep
                    original_pdf = PdfReader(ROOT/dep['source'])
                    expected_solution_pages += len(original_pdf.pages)
                    expected_streams.extend(re.sub(rb'\s+', b' ', p.get_contents().get_data()).strip() for p in original_pdf.pages)
        for variant in ('de','de_solutions'):
            path = ROOT/f'build/{variant}/{chapter}.pdf'
            pdf = PdfReader(path)
            run = sorted(p for p in (CACHE_ROOT/f'latex_runs/{variant}/{chapter}').iterdir() if p.is_dir())[-1]
            log = (run/f'{chapter}.log').read_text(encoding='utf-8',errors='replace')
            aux = (run/f'{chapter}.aux').read_text(encoding='utf-8',errors='replace')
            labels = dict(re.findall(r'\\newlabel\{(ex(?:end)?:[^}]+)\}\{\{[^}]*\}\{(\d+)\}',aux))
            # TeX wraps log lines even in the middle of a dimension or unit.
            compact_log = log.replace('\n', '').replace('\r', '')
            sizes = {key:(float(size),float(limit)) for key,size,limit in
                     re.findall(r'ExerciseSize: ([\w_]+);\s*([\d.]+)pt;\s*([\d.]+)pt',compact_log)}
            for task in tasks:
                key = task['id']
                assert key in sizes, ('Missing task height',path,key)
                if sizes[key][0] <= sizes[key][1]:
                    assert labels['ex:'+key] == labels['exend:'+key], ('Task split across pages',path,key)
            imported = sum(bool(imported_forms(p)) for p in pdf.pages)
            assert imported==(expected_solution_pages if variant=='de_solutions' else 0), (path,imported,expected_solution_pages)
            if variant=='de_solutions':
                for page in pdf.pages: import_bounds(page,pdf,sizes[tasks[0]['id']][1])
                actual_streams = [re.sub(rb'\s+', b' ', x.get_data()).strip() for p in pdf.pages for x in imported_forms(p)]
                assert actual_streams==expected_streams, f'Imported page stream/order differs: {path}'
            if variant=='de':
                text = '\n'.join(p.extract_text() for p in pdf.pages)
                assert 'Mit Musterlösungen' not in text
                assert 'Fachliche Korrektur zur folgenden Original-PDF' not in text
                for r in tasks:
                    canonical = lambda s: re.sub(r'[\W_]+','',s).lower()
                    assert canonical(r['title']) in canonical(text), (path,r['title'])
            summaries.append(dict(path=path.relative_to(ROOT).as_posix(),pages=len(pdf.pages),solution_pages=imported))
    for variant in ('de','de_solutions'):
        combined = PdfReader(ROOT/f'build/{variant}/all_exercises.pdf')
        originals = [page for chapter in chapters for page in PdfReader(ROOT/f'build/{variant}/{chapter}.pdf').pages]
        assert len(combined.pages)==len(originals), 'Combined page count differs'
        assert len(combined.outline)==len(chapters), 'Missing sheet bookmarks'
        offset = 0
        for chapter,bookmark in zip(chapters,combined.outline):
            assert combined.get_destination_page_number(bookmark)==offset, 'Wrong bookmark destination'
            offset += len(PdfReader(ROOT/f'build/{variant}/{chapter}.pdf').pages)
        for before,after in zip(originals,combined.pages):
            assert before.get_contents().get_data()==after.get_contents().get_data(), 'Combined page content differs'
            assert before.extract_text()==after.extract_text(), 'Combined text order differs'
        summaries.append(dict(path=f'build/{variant}/all_exercises.pdf',pages=len(combined.pages),bookmarks=len(combined.outline)))
    (CACHE_ROOT/'verification.json').write_text(json.dumps(summaries,indent=2),encoding='utf-8')
    print(f'Local script reference: {len(reference.pages)} pages. Unchanged originals: {len(inventory["files"])} relocated asset records.')
    print(f'Checked {len(records)} tasks: order, subtask counts, numerical content, solution registration.')
    for row in summaries:
        print(row)


if __name__=='__main__':
    verify()
